import { defineConfig, loadEnv } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'
import seoPrerender from './scripts/seoPrerender.js'

// The sitemap and per-page static HTML are generated by
// scripts/seoPrerender.js after the build (it replaced vite-plugin-sitemap,
// which listed the homepage twice, gave every URL the same priority and date,
// and had no way to include blog posts). Blog posts come from the live API —
// build for production with:
//   SEO_API_URL=https://<your-api-domain>/api npm run build
// (falls back to VITE_API_URL if that isn't localhost).

// https://vite.dev/config/
export default defineConfig(({ mode }) => {
  const env = loadEnv(mode, process.cwd(), '')
  return {
    plugins: [
      react(),
      tailwindcss(),
      seoPrerender({ apiUrl: process.env.SEO_API_URL || env.SEO_API_URL || env.VITE_API_URL }),
    ],
    server: {
      port: 5173,
    },
  }
})
